import sys
from collections import deque

def numberOfEnclaves(grid):
    if not grid or not grid[0]:
        return 0
    n, m = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * m for _ in range(n)]

    def bfs(x, y):
        queue = deque([(x, y)])
        visited[x][y] = True
        is_enclosed = True
        count = 0
        while queue:
            cx, cy = queue.popleft()
            count += 1
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if nx < 0 or nx >= n or ny < 0 or ny >= m:
                    is_enclosed = False
                elif grid[nx][ny] == 1 and not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny))
        return count if is_enclosed else 0

    total_enclaves = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                total_enclaves += bfs(i, j)

    return total_enclaves

input = sys.stdin.read().strip().split('\n')
grid = [list(map(int, row.split())) for row in input]
print(numberOfEnclaves(grid))
